class Solution:
    def maxProfit(self,k,prices):
        if not prices or not k:return 0
        if k>=len(prices)//2:return sum(max(0,b-a) for a,b in zip(prices,prices[1:]))
        buy=[-inf]*(k+1);sell=[0]*(k+1)
        for p in prices:
            for t in range(1,k+1):buy[t]=max(buy[t],sell[t-1]-p);sell[t]=max(sell[t],buy[t]+p)
        return sell[k]
